import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import List from '@mui/joy/List';
import ListSubheader from '@mui/joy/ListSubheader';
import ListItem from '@mui/joy/ListItem';
import ListItemContent from '@mui/joy/ListItemContent';
import ListItemDecorator from '@mui/joy/ListItemDecorator';
import ListItemButton from '@mui/joy/ListItemButton';
// icons
import BubbleChartIcon from '@mui/icons-material/BubbleChart';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import SearchIcon from '@mui/icons-material/Search';
import PeopleRoundedIcon from '@mui/icons-material/PeopleRounded';
import BadgeRoundedIcon from '@mui/icons-material/BadgeRounded';
import BookmarkIcon from '@mui/icons-material/Bookmark';
import BarChartIcon from '@mui/icons-material/BarChart';
import AccountTreeIcon from '@mui/icons-material/AccountTree';
import SlideshowIcon from '@mui/icons-material/Slideshow';
import GridOnIcon from '@mui/icons-material/GridOn';
import ViewColumnIcon from '@mui/icons-material/ViewColumn';
import ViewKanbanIcon from '@mui/icons-material/ViewKanban';
import ContactsIcon from '@mui/icons-material/ContactsOutlined';
import CodeIcon from '@mui/icons-material/CodeOutlined';
import LinkIcon from '@mui/icons-material/LinkOutlined';
import InventoryIcon from '@mui/icons-material/Inventory2Outlined';
import MicIcon from '@mui/icons-material/Mic';
import AccountTreeOutlinedIcon from '@mui/icons-material/AccountTreeOutlined';
import AutoAwesomeIcon from '@mui/icons-material/AutoAwesome';

import { closeSidebar } from '../utils';
import GlobalStyles from '@mui/joy/GlobalStyles';
import { useIsMobile } from '../useMobile';

// The nav panel slides away under the function bar rather than closing to
// nothing, which is why it needs a width it can be pushed left by. It is the
// width the panel already sized itself to from its longest entry - set here so
// that there is a number to animate, not to change how it looks.
const APPBAR_WIDTH = '180px';

export default function AppBar({onActiveApp, activeApp, open = true}: {onActiveApp: React.Dispatch<React.SetStateAction<string>>, activeApp: string, open?: boolean}) {
  const isMobile = useIsMobile();
  return (
    <React.Fragment>
      <GlobalStyles styles={{ ':root': { '--AppBar-width': APPBAR_WIDTH } }} />
      <Box
        className="AppBar-overlay"
        sx={{
          position: 'fixed',
          zIndex: 9998,
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          opacity: 'var(--SideNavigation-slideIn)',
          backgroundColor: 'var(--joy-palette-background-backdrop)',
          transition: 'opacity 0.4s',
          transform: {
            xs: 'translateX(calc(100% * (var(--SideNavigation-slideIn, 0) - 1) + var(--SideNavigation-slideIn, 0) * var(--FunctionBar-width, 0px)))',
            lg: 'translateX(-100%)',
          },
        }}
        onClick={() => closeSidebar()}
      />
      <Sheet
        className="AppBar"
        color="neutral"
        sx={{
          position: {
            xs: 'fixed',
            lg: 'sticky',
          },
          transform: {
            xs: 'translateX(calc(100% * (var(--SideNavigation-slideIn, 0) - 1) + var(--SideNavigation-slideIn, 0) * var(--FunctionBar-width, 0px)))',
            lg: 'none',
          },
          // On a narrow screen this is an off-canvas drawer driven by
          // --SideNavigation-slideIn, which is what the transform above is for.
          // On a wide one it sits in the flow, so closing it means pulling it
          // left out from under the page: the function bar is painted over the
          // top of it (higher z-index) and the rest of the page slides across
          // to take the room back.
          width: { lg: 'var(--AppBar-width)' },
          marginLeft: { lg: open ? 0 : 'calc(-1 * var(--AppBar-width))' },
          transition: 'transform 0.4s, margin-left 0.3s ease',
          zIndex: 9999,
          height: '100dvh',
          top: 0,
          p: 2,
          flexShrink: 0,
          display: 'flex',
          flexDirection: 'column',
          gap: 2,
          borderRight: '1px solid',
          borderColor: 'divider',
          // The drawer is wider under a thumb, because its rows are taller and
          // a 180px column of 44px rows starts wrapping the longer names.
          ...(isMobile ? { width: 224 } : null),
          // The list is seventeen panels and two workspace entries. At desktop
          // row heights that fits a laptop and not much else; at touch heights
          // it fits nothing, and a phone in landscape could not reach the last
          // few entries at all. `minHeight: 0` is what lets the child actually
          // scroll inside a flex column rather than growing past it.
          overflowY: 'auto',
          minHeight: 0,
        }}
      >
        <List
          size="sm"
          sx={{
            '--ListItem-radius': '6px',
            '--List-gap': '6px',
            // 44px is the smallest target a thumb hits first time. The desktop
            // rows stay as they were - a mouse does not need it, and paying 12px
            // a row across nineteen rows is 228px of a laptop screen.
            ...(isMobile ? { '--ListItem-minHeight': '44px' } : null),
          }}
        >
          <ListSubheader role="presentation" sx={{ fontWeight: 'lg' }}>
            Application
          </ListSubheader>
          <ListItem>
            <ListItemButton selected={activeApp === "Agenda"} onClick={() => {onActiveApp("Agenda"); closeSidebar();}}>
              <ListItemDecorator>
                <BubbleChartIcon />
              </ListItemDecorator>
              <ListItemContent>Agenda</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Search"} onClick={() => {onActiveApp("Search"); closeSidebar();}}>
              <ListItemDecorator>
                <SearchIcon />
              </ListItemDecorator>
              <ListItemContent>Search</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "ClockReport"} onClick={() => {onActiveApp("ClockReport"); closeSidebar();}}>
              <ListItemDecorator>
                <AccessTimeIcon />
              </ListItemDecorator>
              <ListItemContent>Clock Report</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "StoredQueries"} onClick={() => {onActiveApp("StoredQueries"); closeSidebar();}}>
              <ListItemDecorator>
                <BookmarkIcon />
              </ListItemDecorator>
              <ListItemContent>Saved Queries</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Files"} onClick={() => {onActiveApp("Files"); closeSidebar();}}>
              <ListItemDecorator>
                <AccountTreeOutlinedIcon />
              </ListItemDecorator>
              <ListItemContent>Files</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Tables"} onClick={() => {onActiveApp("Tables"); closeSidebar();}}>
              <ListItemDecorator>
                <GridOnIcon />
              </ListItemDecorator>
              <ListItemContent>Tables</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Columns"} onClick={() => {onActiveApp("Columns"); closeSidebar();}}>
              <ListItemDecorator>
                <ViewColumnIcon />
              </ListItemDecorator>
              <ListItemContent>Column View</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Code"} onClick={() => {onActiveApp("Code"); closeSidebar();}}>
              <ListItemDecorator>
                <CodeIcon />
              </ListItemDecorator>
              <ListItemContent>Code</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Links"} onClick={() => {onActiveApp("Links"); closeSidebar();}}>
              <ListItemDecorator>
                <LinkIcon />
              </ListItemDecorator>
              <ListItemContent>Links</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Contacts"} onClick={() => {onActiveApp("Contacts"); closeSidebar();}}>
              <ListItemDecorator>
                <ContactsIcon />
              </ListItemDecorator>
              <ListItemContent>Contacts</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Collections"} onClick={() => {onActiveApp("Collections"); closeSidebar();}}>
              <ListItemDecorator>
                <InventoryIcon />
              </ListItemDecorator>
              <ListItemContent>Collections</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Kanban"} onClick={() => {onActiveApp("Kanban"); closeSidebar();}}>
              <ListItemDecorator>
                <ViewKanbanIcon />
              </ListItemDecorator>
              <ListItemContent>Kanban</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "VoiceNotes"} onClick={() => {onActiveApp("VoiceNotes"); closeSidebar();}}>
              <ListItemDecorator>
                <MicIcon />
              </ListItemDecorator>
              <ListItemContent>Voice Notes</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "GanttChart"} onClick={() => {onActiveApp("GanttChart"); closeSidebar();}}>
              <ListItemDecorator>
                <BarChartIcon />
              </ListItemDecorator>
              <ListItemContent>Gantt Chart</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "MindMap"} onClick={() => {onActiveApp("MindMap"); closeSidebar();}}>
              <ListItemDecorator>
                <AccountTreeIcon />
              </ListItemDecorator>
              <ListItemContent>Mind Map</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Starmap"} onClick={() => {onActiveApp("Starmap"); closeSidebar();}}>
              <ListItemDecorator>
                <AutoAwesomeIcon />
              </ListItemDecorator>
              <ListItemContent>Starmap</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton selected={activeApp === "Presentation"} onClick={() => {onActiveApp("Presentation"); closeSidebar();}}>
              <ListItemDecorator>
                <SlideshowIcon />
              </ListItemDecorator>
              <ListItemContent>Presentation</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListSubheader role="presentation" sx={{ fontWeight: 700, mt: 2 }}>
            Workspace
          </ListSubheader>
          <ListItem>
            <ListItemButton onClick={() => closeSidebar()}>
              <ListItemDecorator>
                <PeopleRoundedIcon />
              </ListItemDecorator>
              <ListItemContent>Groups</ListItemContent>
            </ListItemButton>
          </ListItem>
          <ListItem>
            <ListItemButton onClick={() => {onActiveApp("Authentication"); closeSidebar();}}>
              <ListItemDecorator>
                <BadgeRoundedIcon />
              </ListItemDecorator>
              <ListItemContent>Authentication</ListItemContent>
            </ListItemButton>
          </ListItem>
        </List>
      </Sheet>
    </React.Fragment>
  );
}
