// Voice Notes: say something, have it written down, file it as an org heading.
//
// The order of operations is the whole point. A take is uploaded the moment
// recording stops, before anything that can fail is tried on it - so a whisper
// server that is down, a model still loading or a take longer than the timeout
// costs the transcription and never the words. The transcript then comes back
// here to be read and corrected, because a transcript nobody has looked at is a
// guess and an org file is not the place to find that out; what gets written is
// what is on screen when the button is pressed.
//
// Nothing here transcribes anything. The server hands the recording to a
// go-whisper service and this shows what came back.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import Input from '@mui/joy/Input';
import Textarea from '@mui/joy/Textarea';
import Chip from '@mui/joy/Chip';
import Alert from '@mui/joy/Alert';
import Tooltip from '@mui/joy/Tooltip';
import Divider from '@mui/joy/Divider';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Switch from '@mui/joy/Switch';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import FormHelperText from '@mui/joy/FormHelperText';
import Autocomplete from '@mui/joy/Autocomplete';
import CircularProgress from '@mui/joy/CircularProgress';
import LinearProgress from '@mui/joy/LinearProgress';

import MicIcon from '@mui/icons-material/Mic';
import StopIcon from '@mui/icons-material/Stop';
import PauseIcon from '@mui/icons-material/Pause';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import DeleteIcon from '@mui/icons-material/Delete';
import RefreshIcon from '@mui/icons-material/Refresh';
import GraphicEqIcon from '@mui/icons-material/GraphicEq';
import SubtitlesIcon from '@mui/icons-material/Subtitles';
import SaveIcon from '@mui/icons-material/SaveAlt';
import AutoAwesomeIcon from '@mui/icons-material/AutoAwesome';
import ScheduleIcon from '@mui/icons-material/Schedule';

import {
    ODb, VoiceConfig, VoiceRecording, VoiceSegment, VoiceNoteResult,
} from '../db';
import {
    pickMimeType, formatClock, formatBytes, defaultHeadline, recordingName,
    levelOf, excerpt, headlineFromText,
} from '../voice';
import { useChromeToggle } from '../ChromeContext';
import { useIsMobile } from '../useMobile';

// A take: one recording, and whatever is known about it so far. The blob is
// kept for the one that was just made so it can be played without asking the
// server for bytes this browser already has.
type Take = {
    rec: VoiceRecording;
    blob?: Blob;
    url?: string;
    text: string;
    segments: VoiceSegment[];
    model: string;
    language: string;
    transcribing: boolean;
    error: string;
    filed?: VoiceNoteResult;
};

// ---------------------------------------------------------------------------
// The recorder
// ---------------------------------------------------------------------------

type RecorderState = {
    recording: boolean;
    paused: boolean;
    seconds: number;
    level: number;
    error: string;
};

// getUserMedia, a MediaRecorder and an analyser for the level meter, tied to
// the lifetime of this panel.
//
// The elapsed time is counted off the clock rather than off the animation
// frames, because a tab in the background stops painting and would otherwise
// quietly stop counting - the recording carries on regardless, and a timer that
// disagrees with the file is worse than no timer.
function useRecorder(onTake: (blob: Blob, seconds: number, mime: string) => void) {
    const [state, setState] = React.useState<RecorderState>({
        recording: false, paused: false, seconds: 0, level: 0, error: '',
    });

    const stream = React.useRef<MediaStream | null>(null);
    const recorder = React.useRef<MediaRecorder | null>(null);
    const chunks = React.useRef<Blob[]>([]);
    const audioCtx = React.useRef<AudioContext | null>(null);
    const analyser = React.useRef<AnalyserNode | null>(null);
    const raf = React.useRef<number>(0);
    const started = React.useRef<number>(0);
    const paused = React.useRef<number>(0);
    const pausedAt = React.useRef<number>(0);
    const tick = React.useRef<number>(0);
    const onTakeRef = React.useRef(onTake);
    onTakeRef.current = onTake;

    const teardown = React.useCallback(() => {
        if (raf.current) { cancelAnimationFrame(raf.current); raf.current = 0; }
        if (tick.current) { window.clearInterval(tick.current); tick.current = 0; }
        if (stream.current) {
            stream.current.getTracks().forEach(t => t.stop());
            stream.current = null;
        }
        if (audioCtx.current) {
            const ctx = audioCtx.current;
            audioCtx.current = null;
            analyser.current = null;
            ctx.close().catch(() => { });
        }
        recorder.current = null;
    }, []);

    React.useEffect(() => teardown, [teardown]);

    const meter = React.useCallback(() => {
        const a = analyser.current;
        if (!a) return;
        const wave = new Uint8Array(a.fftSize);
        a.getByteTimeDomainData(wave);
        setState(s => (s.recording ? { ...s, level: levelOf(wave) } : s));
        raf.current = requestAnimationFrame(meter);
    }, []);

    const start = React.useCallback(async () => {
        setState(s => ({ ...s, error: '' }));
        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            setState(s => ({ ...s, error: 'This browser will not give a page the microphone. A page served over https or from localhost can ask; anything else cannot.' }));
            return;
        }
        let media: MediaStream;
        try {
            media = await navigator.mediaDevices.getUserMedia({
                audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
            });
        } catch (e: any) {
            const why = e && e.name === 'NotAllowedError'
                ? 'The microphone was refused. Allow it for this site and try again.'
                : e && e.name === 'NotFoundError'
                    ? 'No microphone was found.'
                    : `The microphone could not be opened: ${e && e.message ? e.message : e}`;
            setState(s => ({ ...s, error: why }));
            return;
        }
        stream.current = media;

        const mime = pickMimeType(t => !!(window as any).MediaRecorder && MediaRecorder.isTypeSupported(t));
        let rec: MediaRecorder;
        try {
            rec = mime ? new MediaRecorder(media, { mimeType: mime }) : new MediaRecorder(media);
        } catch (e: any) {
            teardown();
            setState(s => ({ ...s, error: `This browser cannot record audio: ${e && e.message ? e.message : e}` }));
            return;
        }
        chunks.current = [];
        rec.ondataavailable = ev => { if (ev.data && ev.data.size > 0) chunks.current.push(ev.data); };
        rec.onstop = () => {
            const type = rec.mimeType || mime || 'audio/webm';
            const blob = new Blob(chunks.current, { type });
            const seconds = (Date.now() - started.current - paused.current) / 1000;
            chunks.current = [];
            teardown();
            setState({ recording: false, paused: false, seconds: 0, level: 0, error: '' });
            if (blob.size > 0) onTakeRef.current(blob, seconds, type);
        };
        recorder.current = rec;

        try {
            const Ctx = (window as any).AudioContext || (window as any).webkitAudioContext;
            const ctx = new Ctx();
            audioCtx.current = ctx;
            const src = ctx.createMediaStreamSource(media);
            const an = ctx.createAnalyser();
            an.fftSize = 1024;
            src.connect(an);
            analyser.current = an;
        } catch {
            // No meter, which is a shame rather than a problem - the recording
            // is the point and it is already running.
        }

        started.current = Date.now();
        paused.current = 0;
        pausedAt.current = 0;
        // A timeslice, so a long take is delivered in pieces and a browser
        // crash costs the last few seconds rather than all of them.
        rec.start(1000);
        setState({ recording: true, paused: false, seconds: 0, level: 0, error: '' });
        tick.current = window.setInterval(() => {
            setState(s => {
                if (!s.recording || s.paused) return s;
                return { ...s, seconds: (Date.now() - started.current - paused.current) / 1000 };
            });
        }, 200);
        raf.current = requestAnimationFrame(meter);
    }, [meter, teardown]);

    const stop = React.useCallback(() => {
        const rec = recorder.current;
        if (!rec) return;
        if (rec.state !== 'inactive') rec.stop();
    }, []);

    const pause = React.useCallback(() => {
        const rec = recorder.current;
        if (!rec || rec.state !== 'recording') return;
        rec.pause();
        pausedAt.current = Date.now();
        setState(s => ({ ...s, paused: true, level: 0 }));
    }, []);

    const resume = React.useCallback(() => {
        const rec = recorder.current;
        if (!rec || rec.state !== 'paused') return;
        rec.resume();
        if (pausedAt.current) paused.current += Date.now() - pausedAt.current;
        pausedAt.current = 0;
        setState(s => ({ ...s, paused: false }));
    }, []);

    return { state, start, stop, pause, resume };
}

// The level meter: a row of bars that fill from the middle out, which reads as
// a voice rather than as a progress bar.
function Meter({ level, active }: { level: number; active: boolean }) {
    const bars = 24;
    return (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: '3px', height: 28 }}>
            {Array.from({ length: bars }).map((_, i) => {
                const d = Math.abs(i - (bars - 1) / 2) / ((bars - 1) / 2);
                const reach = active ? Math.max(0, level * 1.15 - d * 0.55) : 0;
                const h = 4 + Math.min(1, reach * 2.2) * 22;
                return (
                    <Box
                        key={i}
                        sx={{
                            width: 3, height: h, borderRadius: 2,
                            background: active ? 'var(--joy-palette-danger-solidBg)' : 'var(--joy-palette-neutral-softBg)',
                            opacity: active ? 0.45 + Math.min(1, reach * 2) * 0.55 : 1,
                            transition: 'height 0.08s linear, opacity 0.08s linear',
                        }}
                    />
                );
            })}
        </Box>
    );
}

// ---------------------------------------------------------------------------
// The panel
// ---------------------------------------------------------------------------

export default function VoiceNotes() {
    const isMobile = useIsMobile();
    const chrome = useChromeToggle();

    const [config, setConfig] = React.useState<VoiceConfig | null>(null);
    const [loading, setLoading] = React.useState(true);
    const [takes, setTakes] = React.useState<Take[]>([]);
    const [selected, setSelected] = React.useState<string>('');
    const [message, setMessage] = React.useState('');
    const [uploading, setUploading] = React.useState(false);

    // The note being written, for the selected take.
    const [headline, setHeadline] = React.useState('');
    const [text, setText] = React.useState('');
    const [tags, setTags] = React.useState<string[]>([]);
    const [withTimes, setWithTimes] = React.useState(false);
    const [keepAudio, setKeepAudio] = React.useState(true);
    const [filing, setFiling] = React.useState(false);

    const [model, setModel] = React.useState('');
    const [autoTranscribe, setAutoTranscribe] = React.useState(true);
    const [files, setFiles] = React.useState<string[]>([]);
    const [targetFile, setTargetFile] = React.useState('');
    const [targetHead, setTargetHead] = React.useState('');

    const [playing, setPlaying] = React.useState('');
    const audio = React.useRef<HTMLAudioElement | null>(null);
    const urls = React.useRef<string[]>([]);

    // Object urls are this page's to clean up; a panel that made forty of them
    // and left is forty recordings still in memory.
    React.useEffect(() => () => {
        urls.current.forEach(u => URL.revokeObjectURL(u));
        urls.current = [];
        if (audio.current) { audio.current.pause(); audio.current = null; }
    }, []);

    const load = React.useCallback(async () => {
        setLoading(true);
        const [cfg, recs, refile] = await Promise.all([
            ODb.getVoiceConfig(),
            ODb.getVoiceRecordings(),
            ODb.getRefileTargets(),
        ]);
        setConfig(cfg && cfg.url ? cfg : null);
        if (cfg) {
            setModel(m => m || cfg.model || '');
            // A server with no voice.target configured is the ordinary case for
            // a two line voice block, so the file falls back to an inbox rather
            // than to nothing - the server creates it if it is not there, and
            // the field is right here to be changed. The heading is left empty
            // on purpose: that files at the end of the file, which works
            // whatever is in it.
            setTargetFile(f => f || (cfg.target && cfg.target.Filename) || 'inbox.org');
            setTargetHead(h => h || (cfg.target ? cfg.target.Id : ''));
        }
        setFiles(Array.isArray(refile) ? refile : []);
        setTakes(old => {
            // Anything already on screen keeps its transcript; the rest of the
            // folder joins the list as bare takes.
            const byId = new Map(old.map(t => [t.rec.id, t]));
            return (recs || []).map(r => byId.get(r.id) || {
                rec: r, text: '', segments: [], model: '', language: '',
                transcribing: false, error: '',
            });
        });
        setLoading(false);
    }, []);

    React.useEffect(() => { load(); }, [load]);

    // A model takes a while to load, and the panel should come alive by itself
    // when it has rather than needing the refresh button. Only while it is
    // actually starting: a whisper that is not installed is not going to turn
    // up on its own, and polling for it forever is noise.
    React.useEffect(() => {
        if (!config || config.ready || config.state !== 'starting') return;
        const timer = window.setInterval(async () => {
            const cfg = await ODb.getVoiceConfig();
            if (cfg && cfg.url) setConfig(cfg);
        }, 4000);
        return () => window.clearInterval(timer);
    }, [config]);

    const [restarting, setRestarting] = React.useState(false);
    async function restartWhisper() {
        setRestarting(true);
        await ODb.restartWhisper();
        // Give it a moment to get past "stopped" before asking.
        window.setTimeout(async () => {
            const cfg = await ODb.getVoiceConfig();
            if (cfg && cfg.url) setConfig(cfg);
            setRestarting(false);
        }, 1200);
    }

    const patch = React.useCallback((id: string, p: Partial<Take>) => {
        setTakes(ts => ts.map(t => (t.rec.id === id ? { ...t, ...p } : t)));
    }, []);

    const transcribe = React.useCallback(async (id: string, which: string) => {
        patch(id, { transcribing: true, error: '' });
        const res = await ODb.transcribeVoice(id, which);
        if (!res || res.Ok !== true) {
            patch(id, { transcribing: false, error: (res && res.Msg) || 'The transcription did not come back.' });
            return;
        }
        const segments = res.segments || [];
        patch(id, {
            transcribing: false, error: '',
            text: res.text, segments, model: res.model, language: res.language,
        });
        // Whisper decoded the audio and knows how long it really is; the
        // browser only knew how long the microphone had been open, which is
        // the same thing only if it stopped the instant the talking did.
        if (res.duration > 0) {
            setTakes(ts => ts.map(t => (t.rec.id === id ? { ...t, rec: { ...t.rec, seconds: res.duration } } : t)));
        }
        setSelected(cur => {
            // Only fill the editor in when this is the take being looked at,
            // so a transcription finishing in the background cannot overwrite
            // something being typed about another one.
            if (cur === id) {
                setText(res.text);
                setHeadline(h => (h === '' || h.startsWith('Voice note ') ? headlineFromText(res.text, h) : h));
            }
            return cur;
        });
    }, [patch]);

    // A finished take: uploaded at once, then transcribed if that is switched
    // on and there is anything to transcribe with.
    const onTake = React.useCallback(async (blob: Blob, seconds: number, mime: string) => {
        setUploading(true);
        setMessage('');
        const name = recordingName(mime, new Date());
        const rec = await ODb.saveVoiceRecording(blob, seconds, name);
        setUploading(false);
        if (!rec || !rec.id) {
            setMessage('That recording could not be saved on the server, so it is still only in this tab. Try again before leaving the page.');
            return;
        }
        const url = URL.createObjectURL(blob);
        urls.current.push(url);
        const take: Take = {
            rec, blob, url, text: '', segments: [], model: '', language: '',
            transcribing: false, error: '',
        };
        setTakes(ts => [take, ...ts]);
        setSelected(rec.id);
        setHeadline(defaultHeadline(new Date()));
        setText('');
        setWithTimes(false);
        setKeepAudio(true);
        if (autoTranscribe && config && config.ready) {
            transcribe(rec.id, model);
        }
    }, [autoTranscribe, config, model, transcribe]);

    const recorder = useRecorder(onTake);

    function choose(t: Take) {
        setSelected(t.rec.id);
        setText(t.text);
        setHeadline(t.text ? headlineFromText(t.text, defaultHeadline(new Date(t.rec.created))) : defaultHeadline(new Date(t.rec.created)));
        setWithTimes(false);
        setKeepAudio(true);
    }

    async function play(t: Take) {
        if (playing === t.rec.id) {
            if (audio.current) audio.current.pause();
            setPlaying('');
            return;
        }
        if (audio.current) audio.current.pause();
        let url = t.url;
        if (!url) {
            const blob = await ODb.getVoiceAudio(t.rec.id);
            if (!blob) { setMessage('That recording could not be fetched.'); return; }
            url = URL.createObjectURL(blob);
            urls.current.push(url);
            patch(t.rec.id, { url });
        }
        const el = new Audio(url);
        el.onended = () => setPlaying('');
        el.onerror = () => { setPlaying(''); setMessage('That recording would not play in this browser.'); };
        audio.current = el;
        setPlaying(t.rec.id);
        el.play().catch(() => { setPlaying(''); });
    }

    async function remove(t: Take) {
        if (playing === t.rec.id && audio.current) { audio.current.pause(); setPlaying(''); }
        await ODb.deleteVoiceRecording(t.rec.id);
        setTakes(ts => ts.filter(x => x.rec.id !== t.rec.id));
        if (selected === t.rec.id) { setSelected(''); setText(''); setHeadline(''); }
    }

    async function file() {
        const take = takes.find(t => t.rec.id === selected);
        if (!take) return;
        if (headline.trim() === '') { setMessage('A note needs a headline.'); return; }
        setFiling(true);
        setMessage('');
        const res = await ODb.saveVoiceNote({
            id: take.rec.id,
            headline: headline.trim(),
            text,
            tags,
            target: {
                Filename: targetFile,
                Id: targetHead,
                Type: targetHead ? 'file+headline' : 'file',
                Lvl: 0,
            },
            segments: take.segments,
            withTimes,
            keepAudio,
            model: take.model,
            seconds: take.rec.seconds,
        });
        setFiling(false);
        if (!res || res.Ok !== true) {
            setMessage((res && res.Msg) || 'The note was not filed.');
            return;
        }
        patch(take.rec.id, { filed: res });
        setMessage('');
        if (!keepAudio) {
            setTakes(ts => ts.filter(t => t.rec.id !== take.rec.id));
            setSelected('');
            setText('');
        }
    }

    const take = takes.find(t => t.rec.id === selected) || null;
    const ready = !!(config && config.ready);

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0, gap: 1.5 }}>
            {/* What the server can do */}
            {loading ? (
                <LinearProgress size="sm" />
            ) : !config ? (
                <Alert size="sm" color="danger" variant="soft">
                    The server did not answer about voice notes. It may be an older build without them.
                </Alert>
            ) : !ready ? (
                <Alert
                    size="sm"
                    color={config.state === 'starting' ? 'neutral' : 'warning'}
                    variant="soft"
                    startDecorator={config.state === 'starting' ? <CircularProgress size="sm" /> : undefined}
                    endDecorator={config.managed && config.state !== 'starting' ? (
                        <Button size="sm" variant="soft" loading={restarting} onClick={restartWhisper}>
                            Start it again
                        </Button>
                    ) : undefined}
                >
                    <Box sx={{ minWidth: 0 }}>
                        <Typography level="body-sm" fontWeight="lg">
                            {config.state === 'starting'
                                ? 'Starting whisper'
                                : config.managed
                                    ? 'Whisper did not start'
                                    : 'Nothing to transcribe with yet'}
                        </Typography>
                        <Typography level="body-xs">
                            {config.Msg || 'The whisper server did not answer.'}
                            {config.state === 'starting'
                                ? ' Recording works now; a take made while it loads can be transcribed as soon as it is up.'
                                : ' Recording still works and takes are kept - they can be transcribed once it is up.'}
                        </Typography>
                        {config.log && config.log.length > 0 && (
                            <Box
                                sx={{
                                    mt: 0.75, p: 1, borderRadius: 'sm', maxHeight: 108, overflowY: 'auto',
                                    background: 'var(--joy-palette-background-level1)',
                                    fontFamily: 'monospace', fontSize: 10.5, lineHeight: 1.45,
                                    whiteSpace: 'pre-wrap', wordBreak: 'break-word',
                                }}
                            >
                                {config.log.slice(-8).join('\n')}
                            </Box>
                        )}
                    </Box>
                </Alert>
            ) : null}

            {message && (
                <Alert size="sm" color="warning" variant="soft" endDecorator={
                    <Button size="sm" variant="plain" color="neutral" onClick={() => setMessage('')}>Dismiss</Button>
                }>{message}</Alert>
            )}
            {recorder.state.error && (
                <Alert size="sm" color="danger" variant="soft">{recorder.state.error}</Alert>
            )}

            {/* The recorder */}
            <Sheet variant="outlined" sx={{ borderRadius: 'md', p: 2, display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
                <Tooltip size="sm" title={recorder.state.recording ? 'Stop' : 'Start recording'}>
                    <IconButton
                        variant="solid"
                        color={recorder.state.recording ? 'danger' : 'primary'}
                        onClick={() => (recorder.state.recording ? recorder.stop() : recorder.start())}
                        sx={{
                            '--IconButton-size': '56px', borderRadius: '50%', flexShrink: 0,
                            boxShadow: recorder.state.recording ? '0 0 0 6px var(--joy-palette-danger-softBg)' : 'sm',
                            transition: 'box-shadow 0.25s',
                        }}
                    >
                        {recorder.state.recording ? <StopIcon /> : <MicIcon />}
                    </IconButton>
                </Tooltip>

                <Box sx={{ minWidth: 92 }}>
                    <Typography level="h3" sx={{ fontVariantNumeric: 'tabular-nums', lineHeight: 1 }}>
                        {formatClock(recorder.state.seconds)}
                    </Typography>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        {recorder.state.recording ? (recorder.state.paused ? 'paused' : 'recording') : 'ready'}
                    </Typography>
                </Box>

                <Meter level={recorder.state.level} active={recorder.state.recording && !recorder.state.paused} />

                {recorder.state.recording && (
                    <Button
                        size="sm"
                        variant="soft"
                        color="neutral"
                        startDecorator={recorder.state.paused ? <PlayArrowIcon /> : <PauseIcon />}
                        onClick={() => (recorder.state.paused ? recorder.resume() : recorder.pause())}
                    >
                        {recorder.state.paused ? 'Resume' : 'Pause'}
                    </Button>
                )}
                {uploading && <Chip size="sm" variant="soft" startDecorator={<CircularProgress size="sm" />}>saving</Chip>}

                <Box sx={{ ml: 'auto', display: 'flex', gap: 1.5, alignItems: 'center', flexWrap: 'wrap' }}>
                    {config && config.models && config.models.length > 0 && (
                        <FormControl size="sm">
                            <Select
                                size="sm"
                                value={model}
                                onChange={(_, v) => setModel((v as string) || '')}
                                startDecorator={<GraphicEqIcon fontSize="small" />}
                                sx={{ minWidth: 190 }}
                            >
                                {config.models.map(m => <Option key={m} value={m}>{m}</Option>)}
                            </Select>
                        </FormControl>
                    )}
                    <Tooltip size="sm" title="Transcribe a take as soon as it is recorded">
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
                            <Switch size="sm" checked={autoTranscribe} onChange={e => setAutoTranscribe(e.target.checked)} />
                            <Typography level="body-xs">auto</Typography>
                        </Box>
                    </Tooltip>
                    <Tooltip size="sm" title="Read the recordings folder again">
                        <IconButton size="sm" variant="plain" onClick={load}><RefreshIcon fontSize="small" /></IconButton>
                    </Tooltip>
                </Box>
            </Sheet>

            {/* Takes on the left, the note on the right */}
            {/* Stacked on a phone, side by side otherwise - on the layout flag
                rather than on `md`, so that it agrees with every other panel and
                so that the forced phone layout really is the phone layout. */}
            <Box sx={{ display: 'flex', gap: 1.5, flex: 1, minHeight: 0, minWidth: 0, flexDirection: isMobile ? 'column' : 'row' }}>
                <Sheet
                    variant="outlined"
                    sx={{ borderRadius: 'md', width: isMobile ? 'auto' : 320, minWidth: 0, flexShrink: 0, display: 'flex', flexDirection: 'column', minHeight: 0 }}
                >
                    <Typography level="title-sm" sx={{ px: 1.5, py: 1 }}>
                        Takes {takes.length > 0 && <Chip size="sm" variant="soft">{takes.length}</Chip>}
                    </Typography>
                    <Divider />
                    <Box sx={{ overflowY: 'auto', flex: 1, minHeight: 80 }}>
                        {takes.length === 0 && (
                            <Typography level="body-xs" sx={{ p: 2, color: 'text.tertiary' }}>
                                Nothing recorded yet. The microphone button starts; everything it catches is kept here
                                until it is filed or thrown away.
                            </Typography>
                        )}
                        {takes.map(t => (
                            <Box
                                key={t.rec.id}
                                onClick={() => choose(t)}
                                sx={{
                                    px: 1.5, py: 1, cursor: 'pointer', display: 'flex', gap: 1, alignItems: 'flex-start',
                                    borderLeft: '3px solid',
                                    borderLeftColor: selected === t.rec.id ? 'primary.500' : 'transparent',
                                    background: selected === t.rec.id ? 'var(--joy-palette-primary-softBg)' : 'transparent',
                                    borderBottom: '1px solid', borderBottomColor: 'divider',
                                    '&:hover': { background: 'var(--joy-palette-neutral-softBg)' },
                                }}
                            >
                                <IconButton
                                    size="sm" variant="plain" sx={{ mt: '-2px' }}
                                    onClick={e => { e.stopPropagation(); play(t); }}
                                >
                                    {playing === t.rec.id ? <PauseIcon fontSize="small" /> : <PlayArrowIcon fontSize="small" />}
                                </IconButton>
                                <Box sx={{ minWidth: 0, flex: 1 }}>
                                    <Box sx={{ display: 'flex', gap: 0.75, alignItems: 'center' }}>
                                        <Typography level="body-sm" sx={{ fontVariantNumeric: 'tabular-nums' }}>
                                            {formatClock(t.rec.seconds)}
                                        </Typography>
                                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                            {new Date(t.rec.created).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                            {' · '}{formatBytes(t.rec.bytes)}
                                        </Typography>
                                        {t.filed && <Chip size="sm" variant="soft" color="success" sx={{ '--Chip-minHeight': '16px', fontSize: 10 }}>filed</Chip>}
                                    </Box>
                                    <Typography level="body-xs" sx={{ color: 'text.secondary', mt: 0.25 }}>
                                        {t.transcribing ? 'transcribing…'
                                            : t.error ? <Box component="span" sx={{ color: 'danger.400' }}>{excerpt(t.error, 60)}</Box>
                                                : t.text ? excerpt(t.text, 70)
                                                    : 'not transcribed'}
                                    </Typography>
                                </Box>
                                <IconButton
                                    size="sm" variant="plain" color="danger"
                                    onClick={e => { e.stopPropagation(); remove(t); }}
                                >
                                    <DeleteIcon fontSize="small" />
                                </IconButton>
                            </Box>
                        ))}
                    </Box>
                </Sheet>

                <Sheet variant="outlined" sx={{ borderRadius: 'md', flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                    {!take ? (
                        <Box sx={{ p: 4, textAlign: 'center', color: 'text.tertiary', m: 'auto' }}>
                            <SubtitlesIcon sx={{ fontSize: 40 }} />
                            <Typography level="body-sm" sx={{ mt: 1 }}>
                                Record something, or pick a take, and the note you are about to file appears here.
                            </Typography>
                        </Box>
                    ) : (
                        <Box sx={{ p: 2, display: 'flex', flexDirection: 'column', gap: 1.5, flex: 1, minHeight: 0, overflowY: 'auto' }}>
                            <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap' }}>
                                <Chip size="sm" variant="soft" startDecorator={<ScheduleIcon sx={{ fontSize: 13 }} />}>
                                    {formatClock(take.rec.seconds)}
                                </Chip>
                                {take.model && <Chip size="sm" variant="outlined">{take.model}</Chip>}
                                {take.language && <Chip size="sm" variant="outlined">{take.language}</Chip>}
                                <Box sx={{ ml: 'auto', display: 'flex', gap: 1 }}>
                                    <Button
                                        size="sm"
                                        variant="soft"
                                        startDecorator={take.transcribing ? <CircularProgress size="sm" /> : <AutoAwesomeIcon />}
                                        disabled={!ready || take.transcribing}
                                        onClick={() => transcribe(take.rec.id, model)}
                                    >
                                        {take.text ? 'Transcribe again' : 'Transcribe'}
                                    </Button>
                                </Box>
                            </Box>

                            {take.error && <Alert size="sm" color="danger" variant="soft">{take.error}</Alert>}
                            {take.filed && (
                                <Alert size="sm" color="success" variant="soft">
                                    Filed in {take.filed.filename.split(/[\\/]/).pop()} at line {take.filed.line}.
                                </Alert>
                            )}

                            <FormControl size="sm">
                                <FormLabel>Headline</FormLabel>
                                <Input size="sm" value={headline} onChange={e => setHeadline(e.target.value)} />
                            </FormControl>

                            <FormControl size="sm" sx={{ flex: 1, minHeight: 0 }}>
                                <FormLabel>What was said</FormLabel>
                                <Textarea
                                    size="sm"
                                    minRows={6}
                                    value={take.transcribing && !text ? 'Listening…' : text}
                                    onChange={e => setText(e.target.value)}
                                    placeholder={ready ? 'Transcribe the take, or type the note yourself.' : 'Type the note, or start the whisper server and transcribe.'}
                                    sx={{ fontFamily: 'inherit', lineHeight: 1.5 }}
                                />
                                <FormHelperText>
                                    Corrections here are what gets written - the server files this text, not a fresh transcription.
                                </FormHelperText>
                            </FormControl>

                            {take.segments.length > 0 && (
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <Switch size="sm" checked={withTimes} onChange={e => setWithTimes(e.target.checked)} />
                                    <Typography level="body-xs">
                                        Write the {take.segments.length} timestamped {take.segments.length === 1 ? 'line' : 'lines'} under the note as well
                                    </Typography>
                                </Box>
                            )}

                            <Divider />

                            <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap', alignItems: 'flex-end' }}>
                                <FormControl size="sm" sx={{ minWidth: 200, flex: 1 }}>
                                    <FormLabel>File</FormLabel>
                                    <Autocomplete
                                        size="sm"
                                        freeSolo
                                        options={files}
                                        value={targetFile}
                                        onChange={(_, v) => setTargetFile((v as string) || '')}
                                        onInputChange={(_, v) => setTargetFile(v || '')}
                                        placeholder="inbox.org"
                                    />
                                </FormControl>
                                <FormControl size="sm" sx={{ minWidth: 180, flex: 1 }}>
                                    <FormLabel>Under heading</FormLabel>
                                    <Input
                                        size="sm"
                                        value={targetHead}
                                        onChange={e => setTargetHead(e.target.value)}
                                        placeholder="the end of the file"
                                    />
                                </FormControl>
                                <FormControl size="sm" sx={{ minWidth: 200, flex: 1 }}>
                                    <FormLabel>Tags</FormLabel>
                                    <Autocomplete
                                        size="sm"
                                        multiple
                                        freeSolo
                                        options={[]}
                                        value={tags}
                                        onChange={(_, v) => setTags((v as string[]) || [])}
                                        placeholder={config && config.tags.length > 0 ? config.tags.join(', ') + ' already' : 'none'}
                                    />
                                </FormControl>
                            </Box>

                            <Box sx={{ display: 'flex', gap: 1.5, alignItems: 'center', flexWrap: 'wrap' }}>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75 }}>
                                    <Switch size="sm" checked={keepAudio} onChange={e => setKeepAudio(e.target.checked)} />
                                    <Typography level="body-xs">
                                        {keepAudio ? 'Keep the audio and link to it' : 'Throw the audio away once the words are filed'}
                                    </Typography>
                                </Box>
                                <Button
                                    size="sm"
                                    startDecorator={<SaveIcon />}
                                    loading={filing}
                                    disabled={headline.trim() === ''}
                                    onClick={file}
                                    sx={{ ml: 'auto' }}
                                >
                                    File it
                                </Button>
                            </Box>
                        </Box>
                    )}
                </Sheet>
            </Box>

            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {config ? `whisper at ${config.url}${config.managed ? ' (started by orgs)' : ''}` : ''}
                </Typography>
                <Button size="sm" variant="plain" color="neutral" sx={{ ml: 'auto' }} onClick={() => chrome.setHidden(!chrome.hidden)}>
                    {chrome.hidden ? 'Show the title' : 'More room'}
                </Button>
            </Box>
        </Box>
    );
}
