// A quick look at the numbers in a spreadsheet selection, in a popup over the
// grid.
//
// It used to be one hand-drawn svg line chart, which was the right call while
// there was one picture to draw. There are eighteen now - lines, bars, parts
// of a whole, comparisons - and eighteen hand-rolled layouts is eighteen
// chances to get an axis subtly wrong, so echarts draws them and `chartspec.ts`
// says what to draw. The smooth dotted line with the wash underneath is still
// the default, because that is what this view has always looked like.
//
// echarts is loaded when the popup first opens rather than with the app: it is
// a megabyte, and most sessions never chart anything.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Chip from '@mui/joy/Chip';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Typography from '@mui/joy/Typography';
import Tooltip from '@mui/joy/Tooltip';
import ToggleButtonGroup from '@mui/joy/ToggleButtonGroup';
import Button from '@mui/joy/Button';
import IconButton from '@mui/joy/IconButton';
import CircularProgress from '@mui/joy/CircularProgress';
import Dropdown from '@mui/joy/Dropdown';
import Menu from '@mui/joy/Menu';
import MenuButton from '@mui/joy/MenuButton';
import MenuItem from '@mui/joy/MenuItem';
import ListDivider from '@mui/joy/ListDivider';
import { useColorScheme } from '@mui/joy/styles';
import TableRowsIcon from '@mui/icons-material/TableRows';
import ViewColumnIcon from '@mui/icons-material/ViewColumn';
import InsertChartIcon from '@mui/icons-material/InsertChartOutlined';
import SaveIcon from '@mui/icons-material/Save';
import PostAddIcon from '@mui/icons-material/PostAdd';

import {
    ChartSet, ChartSeries, ChartType, CHART_TYPES, chartTypeInfo, chartOption, ChartLook,
} from '../chartspec';
import { ODb } from '../db';

export type { ChartSeries, ChartSet } from '../chartspec';

// The same selection read both ways round: one series per selected row, or one
// series per selected column. Which one the numbers want depends on how the
// table is laid out, so the reader gets to flip it.
export type ChartInput = { byRow: ChartSet; byCol: ChartSet; prefer: 'byRow' | 'byCol' };

export type CellChartProps = {
    open: boolean;
    onClose: () => void;
    series: ChartInput;
    title: string;
    // Where the table lives, so a chart of it can be filed under it. The last
    // line of the table is where the picture goes - under the table it is a
    // chart of, rather than at the end of whatever heading it happens to be
    // in.
    filename?: string;
    afterLine?: number;
};

const SERIES_COLORS = ['#8b5cf6', '#22c55e', '#3b82f6', '#f59e0b', '#ef4444', '#06b6d4', '#ec4899', '#84cc16'];

// echarts, fetched the first time a chart is opened and kept after.
let echartsMod: any = null;
let echartsWanted: Promise<any> | null = null;
function loadECharts(): Promise<any> {
    if (echartsMod) return Promise.resolve(echartsMod);
    if (!echartsWanted) {
        echartsWanted = import('echarts').then(m => { echartsMod = m; return m; });
    }
    return echartsWanted;
}

export default function CellChart(props: CellChartProps) {
    const { mode, systemMode } = useColorScheme();
    const dark = (mode === 'system' ? systemMode : mode) !== 'light';

    const [orient, setOrient] = React.useState<'byRow' | 'byCol'>(props.series.prefer);
    const [type, setType] = React.useState<ChartType>('smooth');
    const [hidden, setHidden] = React.useState<Record<number, boolean>>({});
    const [ready, setReady] = React.useState(echartsMod !== null);

    const hostRef = React.useRef<HTMLDivElement>(null);
    const chartRef = React.useRef<any>(null);

    // A fresh selection starts over in how it is read and in what is shown -
    // but not in the chart type, which is a preference about reading numbers
    // rather than about these numbers.
    React.useEffect(() => {
        if (props.open) {
            setOrient(props.series.prefer);
            setHidden({});
        }
    }, [props.open, props.series]);

    React.useEffect(() => {
        if (!props.open) return;
        let alive = true;
        loadECharts().then(() => { if (alive) setReady(true); });
        return () => { alive = false; };
    }, [props.open]);

    const set = orient === 'byRow' ? props.series.byRow : props.series.byCol;
    const shownSet: ChartSet = React.useMemo(() => ({
        labels: set.labels,
        series: set.series.filter((_, i) => !hidden[i]),
    }), [set, hidden]);

    const look: ChartLook = React.useMemo(() => ({
        dark,
        // The colours a hidden series leaves behind are not reused, so the
        // fifth series keeps its colour when the second is turned off.
        colors: set.series.map((_, i) => SERIES_COLORS[i % SERIES_COLORS.length])
            .filter((_, i) => !hidden[i]),
        text: dark ? '#c9d1d9' : '#24292f',
        faint: dark ? '#8b93a1' : '#6b7280',
        grid: dark ? '#2b3038' : '#e3e7ec',
        surface: dark ? '#1a1d23' : '#ffffff',
    }), [dark, set.series, hidden]);

    // The chart itself. echarts keeps its own canvas, so React hands it an
    // option and gets out of the way.
    React.useEffect(() => {
        if (!props.open || !ready || !hostRef.current || !echartsMod) return;
        const chart = chartRef.current || echartsMod.init(hostRef.current, undefined, { renderer: 'canvas' });
        chartRef.current = chart;
        chart.setOption(
            chartOption(shownSet, type, look, props.title),
            // Replace rather than merge: a pie left over from the last type
            // would otherwise still be sitting under the bars.
            { notMerge: true },
        );
        chart.resize();
    }, [props.open, ready, shownSet, type, look, props.title]);

    // The popup is sized in viewport units, so the canvas has to be told when
    // the window changes under it.
    React.useEffect(() => {
        const onResize = () => { if (chartRef.current) chartRef.current.resize(); };
        window.addEventListener('resize', onResize);
        return () => window.removeEventListener('resize', onResize);
    }, []);

    React.useEffect(() => {
        if (props.open) return;
        // Taken down with the popup: an echarts instance holds a canvas and a
        // resize observer, and one per selection would pile up.
        if (chartRef.current) {
            chartRef.current.dispose();
            chartRef.current = null;
        }
    }, [props.open]);

    const [filing, setFiling] = React.useState(false);
    const [filed, setFiled] = React.useState('');

    // The chart as a picture in the org directory, linked under its own table.
    //
    // The same endpoint a pasted picture goes through, told where by file and
    // line rather than by heading - a chart belongs under the table it is of,
    // not at the end of the heading the table happens to sit in.
    const fileIntoOrg = async () => {
        const chart = chartRef.current;
        if (!chart || !props.filename) return;
        setFiling(true);
        setFiled('');
        try {
            const url = chart.getDataURL({ type: 'png', pixelRatio: 2, backgroundColor: look.surface });
            const blob = await (await fetch(url)).blob();
            const name = `${(props.title || 'chart').replace(/[^A-Za-z0-9_-]/g, '_')}.png`;
            const res = await ODb.pasteImage('', blob, 'image/png', name, {
                filename: props.filename,
                afterLine: props.afterLine || 0,
            });
            setFiled(res && res.Ok ? `Filed as ${res.link}` : ((res && res.Msg) || 'That did not go through.'));
        } catch (e: any) {
            setFiled((e && e.message) || 'That did not go through.');
        }
        setFiling(false);
    };

    const saveImage = () => {
        const chart = chartRef.current;
        if (!chart) return;
        const url = chart.getDataURL({ type: 'png', pixelRatio: 2, backgroundColor: look.surface });
        const a = document.createElement('a');
        a.href = url;
        a.download = `${(props.title || 'chart').replace(/[^A-Za-z0-9_-]/g, '_')}.png`;
        a.click();
    };

    const info = chartTypeInfo(type);
    const groups: string[] = [];
    for (const c of CHART_TYPES) if (groups.indexOf(c.group) < 0) groups.push(c.group);
    const nothing = shownSet.series.length === 0
        || shownSet.series.every(s => s.points.every(v => v === null));

    return (
        <Modal open={props.open} onClose={props.onClose}>
            <ModalDialog
                variant="outlined"
                layout="center"
                sx={{
                    width: 'min(1040px, 94vw)',
                    maxHeight: '92vh',
                    p: 2,
                    gap: 1.5,
                    borderRadius: 'lg',
                    boxShadow: 'lg',
                    backgroundImage:
                        'linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0) 40%, rgba(0,0,0,0.035)), linear-gradient(180deg, var(--joy-palette-background-surface), var(--joy-palette-background-level1))',
                }}
            >
                <ModalClose />
                <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: 1.5, pr: 4, flexWrap: 'wrap' }}>
                    <Box sx={{ minWidth: 0 }}>
                        <Typography level="title-md" sx={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {props.title}
                        </Typography>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                            {shownSet.series.length} of {set.series.length} series &times; {set.labels.length} points
                            {info.folds && set.series.length > 1 ? ' · added together for this chart' : ''}
                        </Typography>
                    </Box>
                    <Box sx={{ flex: 1 }} />

                    {/* The chart type. A menu rather than a row of buttons:
                        eighteen of them grouped by what they are for is a list
                        you read, not a toolbar you scan. */}
                    <Dropdown>
                        <MenuButton
                            size="sm"
                            variant="outlined"
                            color="neutral"
                            startDecorator={<InsertChartIcon />}
                            sx={{ fontWeight: 'md' }}
                        >
                            {info.label}
                        </MenuButton>
                        {/* Joy stacks a popup at 1000 and a modal at 1300, and
                            this menu is inside a modal - so portalled to the
                            body at its own default it lands underneath the
                            chart. It sits above the dialog and below a tooltip,
                            which is the only place it can be seen and still not
                            cover its own hints. */}
                        <Menu
                            size="sm"
                            placement="bottom-end"
                            sx={{ maxWidth: 340, maxHeight: '60vh', overflow: 'auto', zIndex: 1400 }}
                        >
                            {groups.map((g, gi) => (
                                <React.Fragment key={g}>
                                    {gi > 0 && <ListDivider />}
                                    <Typography
                                        level="body-xs"
                                        sx={{
                                            px: 1.5, pt: 0.75, pb: 0.25, fontWeight: 'lg',
                                            letterSpacing: '0.07em', textTransform: 'uppercase',
                                            color: 'text.tertiary',
                                        }}
                                    >
                                        {g}
                                    </Typography>
                                    {CHART_TYPES.filter(c => c.group === g).map(c => (
                                        <MenuItem
                                            key={c.value}
                                            selected={c.value === type}
                                            onClick={() => setType(c.value)}
                                            sx={{ display: 'block' }}
                                        >
                                            <Typography level="body-sm" sx={{ fontWeight: 'lg' }}>{c.label}</Typography>
                                            <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{c.hint}</Typography>
                                        </MenuItem>
                                    ))}
                                </React.Fragment>
                            ))}
                        </Menu>
                    </Dropdown>

                    <ToggleButtonGroup
                        size="sm"
                        value={orient}
                        onChange={(_, v) => { if (v) setOrient(v as 'byRow' | 'byCol'); }}
                        sx={{ '--ButtonGroup-radius': '8px', backgroundImage: 'linear-gradient(180deg, rgba(255,255,255,0.10), rgba(0,0,0,0.03))' }}
                    >
                        <Tooltip title="One series per selected row" size="sm">
                            <Button value="byRow" startDecorator={<TableRowsIcon />}>Rows</Button>
                        </Tooltip>
                        <Tooltip title="One series per selected column" size="sm">
                            <Button value="byCol" startDecorator={<ViewColumnIcon />}>Columns</Button>
                        </Tooltip>
                    </ToggleButtonGroup>

                    {props.filename && (
                        <Tooltip size="sm" title="Keep this chart in the org directory and link it under the table">
                            <span>
                                <IconButton
                                    size="sm" variant="outlined" color="neutral"
                                    disabled={!ready || filing}
                                    aria-label="File this chart under the table"
                                    onClick={fileIntoOrg}
                                >
                                    {filing
                                        ? <CircularProgress size="sm" sx={{ '--CircularProgress-size': '16px' }} />
                                        : <PostAddIcon fontSize="small" />}
                                </IconButton>
                            </span>
                        </Tooltip>
                    )}
                    <Tooltip size="sm" title="Download this chart as a PNG">
                        <span>
                            <IconButton size="sm" variant="outlined" color="neutral" disabled={!ready} onClick={saveImage}>
                                <SaveIcon fontSize="small" />
                            </IconButton>
                        </span>
                    </Tooltip>
                </Box>

                <Box
                    sx={{
                        borderRadius: 'md',
                        border: '1px solid',
                        borderColor: 'divider',
                        overflow: 'hidden',
                        position: 'relative',
                        height: 'min(56vh, 460px)',
                        backgroundImage: 'linear-gradient(180deg, var(--joy-palette-background-surface), var(--joy-palette-background-level1))',
                    }}
                >
                    <Box ref={hostRef} sx={{ width: '100%', height: '100%' }} />
                    {!ready && (
                        <Box sx={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                            <CircularProgress size="sm" />
                        </Box>
                    )}
                    {ready && nothing && (
                        <Box sx={{ position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', pointerEvents: 'none' }}>
                            <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>
                                Nothing numeric in this selection
                            </Typography>
                        </Box>
                    )}
                </Box>

                <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', alignItems: 'center' }}>
                    {set.series.map((s, i) => {
                        const color = SERIES_COLORS[i % SERIES_COLORS.length];
                        const off = hidden[i] === true;
                        return (
                            <Chip
                                key={i}
                                size="sm"
                                variant="outlined"
                                onClick={() => setHidden(h => ({ ...h, [i]: !off }))}
                                sx={{
                                    borderRadius: '7px',
                                    opacity: off ? 0.45 : 1,
                                    backgroundImage: 'linear-gradient(180deg, rgba(255,255,255,0.08), rgba(0,0,0,0.02))',
                                }}
                                startDecorator={
                                    <Box
                                        sx={{
                                            width: 9,
                                            height: 9,
                                            borderRadius: '50%',
                                            backgroundColor: off ? 'transparent' : color,
                                            boxShadow: `inset 0 0 0 2px ${color}`,
                                        }}
                                    />
                                }
                            >
                                {s.name}
                            </Chip>
                        );
                    })}
                    <Box sx={{ flex: 1 }} />
                    <Typography level="body-xs" sx={{ color: filed !== '' ? 'text.secondary' : 'text.tertiary' }}>
                        {filed !== '' ? filed : 'Click a name to hide its series · Esc closes'}
                    </Typography>
                </Box>
            </ModalDialog>
        </Modal>
    );
}
