// The colour schemes the org source view can be read in.
//
// Each scheme is written down as the handful of colours its authors actually
// published - a ground, a foreground, a comment grey and six or seven accents -
// and the forty-odd roles org needs are derived from those by one builder. That
// is the only way a list this long stays honest: forty hand-picked values per
// theme is forty chances to quietly use Monokai's pink where One Dark's red
// belongs, and nobody would ever notice.
//
// It also means a new theme is a dozen lines of real colour values rather than
// a wall of guesses, and that every theme colours the same org construct with
// the same *kind* of colour - headings run through the accents in one order,
// strings are always the green-ish one - so switching theme changes the mood
// without changing what the colours mean.

export type Palette = Record<string, string>;

// What a scheme actually publishes. `muted` is the dimmer of the two greys -
// what a comment is written in - and `faint` the one used for rules and
// punctuation that should be felt rather than read.
interface Base {
    dark: boolean;
    bg: string;
    fg: string;
    gutter: string;
    gutterBg: string;
    sel: string;
    muted: string;
    faint: string;
    red: string;
    orange: string;
    yellow: string;
    green: string;
    cyan: string;
    blue: string;
    purple: string;
}

// Two colours blended, for a role that wants to sit between two of a scheme's
// own. `t` is how far to go from `a` towards `b`.
//
// Used for the punctuation inside code, which needs to land between "felt
// rather than read" and "read". Worked out from each scheme's own colours
// rather than picked by hand eleven times, so a scheme added later gets it
// right without anybody thinking about it.
function mix(a: string, b: string, t: number): string {
    const hex = (c: string) => {
        const v = c.trim().replace('#', '');
        const full = v.length === 3 ? v.split('').map(x => x + x).join('') : v;
        const n = parseInt(full, 16);
        return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
    };
    // Anything that is not a plain hex colour is left alone rather than
    // mangled - a scheme may reasonably publish an rgba() somewhere.
    if (!/^#[0-9a-fA-F]{3}([0-9a-fA-F]{3})?$/.test(a.trim()) ||
        !/^#[0-9a-fA-F]{3}([0-9a-fA-F]{3})?$/.test(b.trim())) {
        return a;
    }
    const [ar, ag, ab] = hex(a);
    const [br, bg, bb] = hex(b);
    const at = (x: number, y: number) => Math.round(x + (y - x) * t);
    const two = (n: number) => n.toString(16).padStart(2, '0');
    return `#${two(at(ar, br))}${two(at(ag, bg))}${two(at(ab, bb))}`;
}

// The org roles, in terms of the scheme's own colours. Read this as the theme
// contract: change a line here and every scheme changes with it.
function build(b: Base): Palette {
    return {
        bg: b.bg,
        fg: b.fg,
        gutter: b.gutter,
        gutterBg: b.gutterBg,

        // Heading levels walk the accents rather than fading out, because in a
        // deep outline the level is the thing you are trying to see.
        h1: b.blue, h2: b.green, h3: b.yellow, h4: b.purple, h5: b.cyan, h6: b.red,
        stars: b.faint,

        todo: b.red,
        doneKw: b.muted,
        priority: b.orange,
        tag: b.cyan,

        comment: b.muted,
        keyword: b.cyan,
        keywordArg: b.green,
        blockDelim: b.purple,
        blockBody: b.fg,

        // The code inside a #+BEGIN_SRC block, painted out of this scheme's
        // own colours - so a block of python in a Nord file looks like Nord.
        // The scanner that decides which run of characters is which lives in
        // src/codehl.ts; all a scheme has to publish is these roles.
        codeKeyword: b.purple,
        codeString: b.green,
        codeComment: b.muted,
        codeNumber: b.orange,
        codeFunc: b.blue,
        codeType: b.yellow,
        codeBuiltin: b.cyan,

        // Punctuation in code is not the same job as punctuation in prose.
        // `faint` is the right weight for a horizontal rule - felt rather than
        // read - and the wrong one for a brace: in Solarized Dark it is
        // #073642 on a #002b36 ground, which is a brace you have to hunt for.
        // Both are lifted towards the foreground, the operators further,
        // because `:=` is something a reader is *reading* while `{` is
        // something they are only locating.
        codePunct: mix(b.faint, b.fg, 0.6),
        codeOp: mix(b.faint, b.fg, 0.85),

        drawer: b.purple,
        propKey: b.cyan,
        propVal: b.fg,

        planning: b.yellow,
        tsActive: b.cyan,
        tsInactive: b.muted,

        table: b.blue,
        tableRule: b.faint,
        bullet: b.yellow,
        checkDone: b.green,
        checkOpen: b.muted,

        linkPunct: b.faint,
        linkTarget: b.cyan,
        linkDesc: b.green,

        markup: b.faint,
        bold: b.fg,
        italic: b.purple,
        underline: b.fg,
        verbatim: b.green,
        code: b.cyan,
        strike: b.muted,
        footnote: b.orange,
        rule: b.faint,
        selBg: b.sel,
    };
}

export interface OrgTheme {
    key: string;
    label: string;
    dark: boolean;
    palette: Palette;
}

