// Follow the app's own light and dark rather than naming a scheme.
export const ORG_THEME_AUTO = 'auto';

const BY_KEY: Record<string, OrgTheme> = {};
ORG_THEMES.forEach(t => { BY_KEY[t.key] = t; });

export function orgTheme(key: string): OrgTheme | null {
    return BY_KEY[key] || null;
}

// The palette to read a file in. "auto" is not a scheme of its own: it is
// whichever of the two default schemes matches the app, so that a reader who
// has never thought about this still gets a source view that belongs to the
// page around it.
export function orgPalette(key: string, appIsDark: boolean): Palette {
    if (key !== ORG_THEME_AUTO) {
        const t = BY_KEY[key];
        if (t) return t.palette;
    }
    return (appIsDark ? BY_KEY['default-dark'] : BY_KEY['default-light']).palette;
}
